contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address user) public payable {
        require(user != address(0));
        require(c.getBalance(user) == 0);

        uint256 cBalanceBefore = address(c).balance;
        uint256 storedBefore = c.getBalance(user); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (address(c).balance == cBalanceBefore && c.getBalance(user) == storedBefore));
    }

    receive() external payable {}
}

