pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address user) internal {
        vm.assume(user != address(0));
        vm.assume(c.getBalance(user) == 0);
        uint256 cBalanceBefore = address(c).balance;
        uint256 storedBefore;
        try c.getBalance(user) returns (uint256 __r) { storedBefore = __r; } catch { return; }
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == cBalanceBefore && c.getBalance(user) == storedBefore));
    }

    function testFuzz_run(address user) public {
        vm.assume(user.code.length == 0 && uint160(user) > 0xffff && user != address(this) && user != address(c) && user != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && user != 0x000000000000000000636F6e736F6c652e6c6f67 && user != 0x4e59b44847b379578588920cA78FbF26c0B4956C && user != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(user);
    }

    receive() external payable {}
}
